  "note": "组件 mount/update/dispose、可选 suspend/resume 和 scope、目标、事件、状态、媒体、互动、教师控制器端口取自正式合同。__runtime.activity 按实例回放 active/visible/playing，暂时离屏保留同一 mount；暂停为程序协作，不是任意网页硬冻结。相关类型保留原源码引用路径；实际端口由当前宿主提供。",
  "source": "src/shared/contracts/component-platform/runtime.ts",
  "types": {
    "src/shared/contracts/component-platform/frame.ts": "/** Maps local content coordinates to the owning parent's coordinates. */\nexport type AffineTransform = [number, number, number, number, number, number]\n\nexport interface ComponentFrame {\n  width: number\n  height: number\n  transform: AffineTransform\n}\n\nexport const identityTransform = (): AffineTransform => [1, 0, 0, 1, 0, 0]\n",
    "src/shared/contracts/component-platform/motion.ts": "/** Temporary local transforms compose after the current author transform. */\nexport interface MotionFrame {\n  readonly transform?: string\n  /** Temporary opacity scale, sampled when a task starts. */\n  readonly opacity?: number\n}\n\nexport interface MotionKeyframe extends MotionFrame {\n  readonly offset?: number\n  readonly easing?: string\n}\n\n/** Serializable timing supported by the shared motion presentation service. */\nexport interface MotionTiming {\n  readonly delay?: number\n  readonly direction?: 'normal' | 'reverse' | 'alternate' | 'alternate-reverse'\n  readonly duration?: number | 'auto'\n  readonly easing?: string\n  readonly endDelay?: number\n  readonly fill?: 'none' | 'forwards' | 'backwards' | 'both' | 'auto'\n  readonly iterationStart?: number\n  readonly iterations?: number\n}\n\nexport interface ComponentMotionContext {\n  readonly signal: AbortSignal\n  readonly reducedMotion: boolean\n  /** Resolves only after the host applies the frame; false means this task retired. */\n  write(frame: MotionFrame): Promise<boolean>\n  nextFrame(): Promise<{ readonly elapsed: number } | null>\n  animate(frames: readonly MotionKeyframe[], timing: MotionTiming): Promise<boolean>\n  onCleanup(cleanup: () => void): void\n}\n\n/** Executed in the calling implementation's realm; functions never cross the host port. */\nexport type ComponentMotionProgram = (context: ComponentMotionContext) => void | Promise<void>\nexport type ComponentMotionOutcome =\n  | { readonly status: 'completed' | 'cancelled' }\n  | { readonly status: 'failed'; readonly error: unknown }\n\nexport interface ComponentMotionTask {\n  readonly finished: Promise<ComponentMotionOutcome>\n  cancel(): void\n}\n\nexport interface ComponentMotionPort {\n  /** A channel is private to this source mount and target. */\n  replace(channel: string, program: ComponentMotionProgram): ComponentMotionTask\n}\n",
    "src/shared/contracts/component-platform/navigationMotion.ts": "import { z } from 'zod'\nimport type { MotionKeyframe } from './motion'\n\nexport interface ComponentCameraPose { x: number; y: number; zoom: number; rotation?: number }\n/** Intermediate poses are sampled within one finite presentation, not stored camera frames. */\nexport interface ComponentCameraMotion {\n  durationMs?: number\n  /** Any CSS easing, including cubic-bezier() and code-generated linear() curves. */\n  easing?: string\n  keyframes?: readonly { offset: number; pose: ComponentCameraPose; easing?: string }[]\n}\n/** Generate these keyframes in ordinary code; delays/offsets coordinate both snapshots. */\nexport interface ComponentNavigationTransition {\n  /** Small presets share the snapshot owner with authored advanced keyframes. */\n  effect?: 'none' | 'fade' | 'slide' | 'zoom'\n  durationMs?: number\n  easing?: string\n  direction?: 'left' | 'right' | 'up' | 'down'\n  outgoing?: { keyframes: readonly MotionKeyframe[]; timing?: { duration?: number; delay?: number; easing?: string } }\n  incoming?: { keyframes: readonly MotionKeyframe[]; timing?: { duration?: number; delay?: number; easing?: string } }\n}\nexport interface ComponentNavigationMotion {\n  transition?: ComponentNavigationTransition\n  camera?: ComponentCameraMotion\n}\nexport const componentCameraPoseSchema: z.ZodType<ComponentCameraPose> = z.object({\n  x: z.number().finite(), y: z.number().finite(), zoom: z.number().finite().positive(), rotation: z.number().finite().optional(),\n}).strict()\nexport const componentCameraMotionSchema: z.ZodType<ComponentCameraMotion> = z.object({\n  durationMs: z.number().finite().nonnegative().optional(), easing: z.string().min(1).optional(),\n  keyframes: z.array(z.object({ offset: z.number().gt(0).lt(1), pose: componentCameraPoseSchema, easing: z.string().min(1).optional() }).strict())\n    .refine(frames => frames.every((frame, index) => index === 0 || frame.offset > frames[index - 1]!.offset), '镜头关键 pose 的 offset 必须递增').optional(),\n}).strict()\nconst snapshotMotionSchema = z.object({\n  keyframes: z.array(z.object({ transform: z.string().optional(), opacity: z.number().finite().optional(), offset: z.number().min(0).max(1).optional(), easing: z.string().optional() }).strict()).min(1),\n  timing: z.object({ duration: z.number().finite().nonnegative().optional(), delay: z.number().finite().nonnegative().optional(), easing: z.string().min(1).optional() }).strict().optional(),\n}).strict()\nexport const componentNavigationTransitionSchema: z.ZodType<ComponentNavigationTransition> = z.object({\n  effect: z.enum(['none', 'fade', 'slide', 'zoom']).optional(),\n  durationMs: z.number().finite().nonnegative().optional(), easing: z.string().min(1).optional(),\n  direction: z.enum(['left', 'right', 'up', 'down']).optional(),\n  outgoing: snapshotMotionSchema.optional(), incoming: snapshotMotionSchema.optional(),\n}).strict()\n",
    "src/shared/contracts/component-platform/project.ts": "import type { FlowTextContent } from '../../document/content'\r\nimport type { ComponentFrame } from './frame'\r\nimport type { CourseStateDeclaration, CourseStateCondition } from '../course-state/types'\r\nimport type { ProjectDesignTokens, CourseTheme } from '../design-v1/types'\r\nimport type { ProjectPlaybackSettings } from '../playback-v1/types'\r\nimport type { AssetSource, ProjectMediaSettings } from '../media-v1/types'\r\nimport type { ComponentAuthorRecord } from './runtime'\r\n\r\nexport type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue }\r\nexport type JsonObject = { [key: string]: JsonValue }\r\nexport type ComponentRole = 'content' | 'behavior' | 'mixed'\r\n\r\nexport type ComponentImplementation =\r\n  | { kind: 'builtin'; key: string }\r\n  | ({ kind: 'source'; language: 'javascript' | 'typescript'; dependencies?: string[];\r\n      /** Original module specifiers map to definitions within this source owner. */\r\n      moduleBindings?: Record<string, string>;\r\n      /** Software-owned resource names preserve source lookups when library assets receive new identities. */\r\n      resourceBindings?: Record<string, string> } & (\r\n      | { source: string; workspace?: never }\r\n      /** Files, including the entry, live only in DocumentResources.components[ownerId]. */\r\n      | { workspace: { ownerId: string; entry: string }; source?: never }\r\n    ))\r\n\r\nexport interface ComponentDefinition {\r\n  readonly id: string\r\n  role: ComponentRole\r\n  implementation: ComponentImplementation\r\n  /** Professional schemas belong to the definition, never to an editor carrier. */\r\n  dataSchema?: JsonObject\r\n  /** Retains professional authoring when the definition uses custom source. */\r\n  professionalBuiltinKey?: string\r\n  version?: string\r\n  title?: string\r\n  library?:{packageId:string;version?:string}\r\n}\r\n\r\n/** Authoring identity only. Runtime always resolves the effective implementation. */\r\nexport function componentDefinitionBuiltinKey(definition: ComponentDefinition | undefined): string | undefined {\r\n  return definition?.implementation.kind === 'builtin' ? definition.implementation.key : definition?.professionalBuiltinKey\r\n}\r\n\r\nexport type ComponentTarget =\r\n  | { kind: 'instance'; instanceId: string }\r\n  | { kind: 'text-range'; instanceId: string; dataPath: string[]; rangeId: string }\r\n  | { kind: 'surface'; surfaceId: string }\r\n  | { kind: 'project' }\r\n\r\nexport interface BehaviorAttachment {\r\n  instanceId: string\r\n  target: ComponentTarget\r\n}\r\n\r\n/** Persistent author changes belong to the instance, independently of its business data or renderer. */\r\nexport interface ComponentAuthoring {\r\n  records?: Record<string, ComponentAuthorRecord>\r\n  resourceBindings?: Record<string, string>\r\n}\r\n\r\nexport interface ComponentInstance<Data = JsonValue> {\r\n  readonly id: string\r\n  definitionId: string\r\n  name?: string\r\n  visible?: boolean\r\n  visibility?: { mode: 'all' | 'include' | 'exclude'; surfaceIds: string[] }\r\n  locked?: boolean\r\n  /** Explicit viewport projection for global controls, independent of navigation privileges. */\r\n  viewportPinned?: boolean\r\n  playbackInitialVisibility?: 'inherit' | 'hidden'\r\n  flowPlacement?: ComponentFlowPlacement\r\n  flowLayout?: ComponentFlowBodyLayout\r\n  /** Explicit Source aliases for declared scalar course state; identities follow canonical rename/copy. */\r\n  stateBindings?: Record<string, string>\r\n  data: Data\r\n  authoring?: ComponentAuthoring\r\n  style?: JsonObject\r\n  frame?: ComponentFrame\r\n  /** The sole ownership and ordering relation; parent indexes are derived. */\r\n  childIds?: string[]\r\n  attachments?: BehaviorAttachment[]\r\n  implementationOverride?: ComponentImplementation\r\n}\r\n\r\nexport interface ComponentBackground {\r\n  mode?: 'inherit' | 'own'\r\n  color?: string\r\n  assetId?: string | null\r\n  fit?: 'cover' | 'contain' | 'fill'\r\n  /** Background-only paint, back to front. It owns no author instances or layout. */\r\n  paint?: ComponentBackgroundPaint | null\r\n}\r\nexport type ComponentBackgroundProperty = 'background-color' | 'background-image' | 'background-size'\r\n  | 'background-position' | 'background-repeat' | 'background-origin' | 'background-clip'\r\n  | 'background-attachment' | 'background-blend-mode'\r\nexport interface ComponentBackgroundPaint {\r\n  layers: { style: Partial<Record<ComponentBackgroundProperty, string>>; resourceBindings: Record<string, string> }[]\r\n}\r\nexport interface ResolvedComponentBackground {\r\n  color: string\r\n  assetId: string | null\r\n  fit: 'cover' | 'contain' | 'fill'\r\n  paint?: ComponentBackgroundPaint\r\n}\r\nexport interface ComponentFlowBodyLayout {\r\n  width: 'content-width' | 'wide' | 'full-width'\r\n  wrap?: 'none' | 'left' | 'right'\r\n  caption?: FlowTextContent\r\n}\r\nexport interface ComponentFlowPlacement {\r\n  space: 'paper' | 'viewport'\r\n  plane: 'overlay' | 'underlay'\r\n  paragraphAnchor?: { blockId: string; offsetY: number; xRatio: number }\r\n}\r\nexport interface ComponentFlowAuthoring {\r\n  layout: { toc?: 'auto' | 'hidden'; widthMode?: 'fluid' | 'reading'; readingWidth: number; wideContentWidth: number; paperBackgroundColor?: string }\r\n}\r\nexport interface ComponentPresentationState {\r\n  id: string\r\n  title: string\r\n  overrides: Record<string, { data?: JsonValue; authoring?: ComponentAuthoring; style?: JsonObject; frame?: ComponentFrame | null; visible?: boolean; playbackInitialVisibility?: 'inherit' | 'hidden' }>\r\n  /** Display order only; the surface childIds remains the ownership relation. */\r\n  order?: string[]\r\n  background?: ComponentBackground\r\n}\r\nexport interface ComponentPresentation {\r\n  states: ComponentPresentationState[]\r\n  initialStateId?: string | null\r\n  thumbnailStateId?: string | null\r\n}\r\nexport interface CourseProjectLogic {\r\n  courseState: CourseStateDeclaration[]\r\n  navigationGuards: { id: string; effect: 'block'; fromSurfaceIds?: string[]; toSurfaceIds: string[];\r\n    match: 'all' | 'any'; conditions: CourseStateCondition[]; message: string }[]\r\n  network?: { connectOrigins?: string[] }\r\n}\r\n\r\nexport interface ComponentSurface {\r\n  id: string\r\n  kind: 'slide' | 'flow' | 'spatial'\r\n  title: string\r\n  childIds: string[]\r\n  designSize?: { width: number; height: number }\r\n  spatial?: ComponentSpatialAuthoring\r\n  background?: ComponentBackground\r\n  flow?: ComponentFlowAuthoring\r\n  presentation?: ComponentPresentation\r\n}\r\n\r\n/** Pose x/y are the viewport center in world coordinates; rotation is degrees. */\r\nexport interface ComponentSpatialPose { x: number; y: number; zoom: number; rotation?: number }\r\nexport interface ComponentSpatialAuthoring {\r\n  /** Missing/null means authored frames order; reads never materialize a default. */\r\n  defaultPathId?: string | null\r\n  home: ComponentSpatialPose\r\n  frames: { id: string; title?: string; pose: ComponentSpatialPose; targetInstanceId?: string }[]\r\n  paths?: { id: string; title?: string; frameIds: string[]; instanceIds?: string[];\r\n    style?: { color?: string; width?: number; dash?: 'solid' | 'dashed' | 'dotted' } }[]\r\n  relations?: { id: string; sourceInstanceId: string; targetInstanceId: string; label?: string; kind: 'line' | 'arrow' | 'bidirectional' }[]\r\n  semanticZoom?: { id: string; instanceIds: string[]; minZoom: number; maxZoom: number; visible: boolean }[]\r\n}\r\n\r\nexport interface ComponentAsset {\r\n  id: string\r\n  path: string\r\n  mimeType?: string\r\n  filename?: string\r\n  kind?: 'image' | 'audio' | 'video' | 'font'\r\n  byteLength?: number\r\n  width?: number\r\n  height?: number\r\n  duration?: number\r\n  /** HTTPS delivery of the same embedded bytes; provenance remains in source. */\r\n  remote?: { url: string }\r\n  source?: AssetSource\r\n}\r\n\r\nexport interface CourseProjectV10 {\r\n  schemaVersion: 10\r\n  id: string\r\n  revision: number\r\n  title: string\r\n  background?: ComponentBackground\r\n  designTokens?: ProjectDesignTokens\r\n  theme?: CourseTheme\r\n  playback?: ProjectPlaybackSettings\r\n  media?: ProjectMediaSettings\r\n  logic?: CourseProjectLogic\r\n  definitions: Record<string, ComponentDefinition>\r\n  instances: Record<string, ComponentInstance>\r\n  surfaces: ComponentSurface[]\r\n  global: { underlay: string[]; overlay: string[] }\r\n  assets: Record<string, ComponentAsset>\r\n}\r\n\r\nexport type ComponentContainer =\r\n  | { kind: 'instance'; instanceId: string }\r\n  | { kind: 'surface'; surfaceId: string }\r\n  | { kind: 'global'; plane: 'underlay' | 'overlay' }\r\n\r\nexport function containerChildIds(project: CourseProjectV10, container: ComponentContainer): string[] {\r\n  if (container.kind === 'global') return project.global[container.plane]\r\n  if (container.kind === 'surface') {\r\n    const surface = project.surfaces.find(value => value.id === container.surfaceId)\r\n    if (!surface) throw new Error(`表面已不存在：${container.surfaceId}`)\r\n    return surface.childIds\r\n  }\r\n  const instance = project.instances[container.instanceId]\r\n  if (!instance?.childIds) throw new Error(`容器已不存在：${container.instanceId}`)\r\n  return instance.childIds\r\n}\r\n\r\nexport function owningContainer(project: CourseProjectV10, instanceId: string): ComponentContainer | null {\r\n  for (const plane of ['underlay', 'overlay'] as const) if (project.global[plane].includes(instanceId)) return { kind: 'global', plane }\r\n  for (const surface of project.surfaces) if (surface.childIds.includes(instanceId)) return { kind: 'surface', surfaceId: surface.id }\r\n  for (const instance of Object.values(project.instances)) if (instance.childIds?.includes(instanceId)) return { kind: 'instance', instanceId: instance.id }\r\n  return null\r\n}\r\n\r\n/** An object's editing lock includes its containing groups. */\r\nexport function componentIsLocked(project: CourseProjectV10, id: string): boolean {\r\n  if (project.instances[id]?.locked) return true\r\n  const owner = owningContainer(project, id)\r\n  return owner?.kind === 'instance' ? componentIsLocked(project, owner.instanceId) : false\r\n}\r\n\r\nexport function isComponentVisibleAtSurface(instance: Pick<ComponentInstance, 'visible' | 'visibility'>, surfaceId: string): boolean {\r\n  if (instance.visible === false) return false\r\n  const scope = instance.visibility\r\n  return !scope || scope.mode === 'all' || (scope.mode === 'include' ? scope.surfaceIds.includes(surfaceId) : !scope.surfaceIds.includes(surfaceId))\r\n}\r\n\r\n/** One effective paint rule for editors, Player and output. */\r\nexport function resolveComponentBackground(project: Pick<CourseProjectV10, 'background'>, surface?: Pick<ComponentSurface, 'background'>, state?: Pick<ComponentPresentationState, 'background'>): ResolvedComponentBackground {\r\n  const base = project.background\r\n  const selected = surface?.background?.mode === 'own' ? surface.background : base\r\n  const result: ResolvedComponentBackground = selected?.paint ? { color: '#ffffff', assetId: null, fit: 'cover', paint: selected.paint }\r\n    : { color: selected?.color ?? '#ffffff', assetId: selected?.assetId ?? null, fit: selected?.fit ?? 'cover' as const }\r\n  const override = state?.background\r\n  if (!override || override.mode === 'inherit') return result\r\n  if (override.paint) return { color: '#ffffff', assetId: null, fit: 'cover', paint: override.paint }\r\n  const replacesPaint = override.paint === null || ['color', 'assetId', 'fit'].some(key => Reflect.get(override, key) !== undefined)\r\n  if (result.paint && !replacesPaint) return result\r\n  const inherited = result.paint ? { color: '#ffffff', assetId: null, fit: 'cover' as const } : result\r\n  return { color: override.color ?? inherited.color, assetId: override.assetId === undefined ? inherited.assetId : override.assetId,\r\n    fit: override.fit ?? inherited.fit }\r\n}\r\n\r\n/** A disposable render/edit projection. It never becomes an authoring write source. */\r\nexport function resolveComponentPresentation(project: CourseProjectV10, surfaceId: string | null, stateId: string | null): CourseProjectV10 {\r\n  const surface = project.surfaces.find(value => value.id === surfaceId)\r\n  const state = surface?.presentation?.states.find(value => value.id === stateId)\r\n  if (!surface || !state) return project\r\n  const instances = { ...project.instances }\r\n  for (const [id, override] of Object.entries(state.overrides)) if (instances[id]) {\r\n    const { frame, ...fields } = override\r\n    const instance = { ...instances[id], ...fields }\r\n    if (frame === null) delete instance.frame\r\n    else if (frame !== undefined) instance.frame = frame\r\n    instances[id] = instance\r\n  }\r\n  const order = state.order?.filter(id => surface.childIds.includes(id))\r\n  const background = state.background && resolveComponentBackground(project, surface, state)\r\n  const projectedSurface = { ...surface,\r\n    ...(order ? { childIds: [...order, ...surface.childIds.filter(id => !order.includes(id))] } : {}),\r\n    ...(background ? { background: background.paint ? { mode: 'own' as const, paint: background.paint }\r\n      : { mode: 'own' as const, ...background } } : {}),\r\n  }\r\n  return { ...project, instances, surfaces: project.surfaces.map(value => value.id === surfaceId ? projectedSurface : value) }\r\n}\r\n",
    "src/shared/contracts/component-platform/runtime.ts": "import type { AffineTransform, ComponentFrame } from './frame'\r\nimport type { ComponentInstance, ComponentTarget, JsonValue } from './project'\r\nimport type { TeacherControllerPort } from './teacherController'\r\nimport type { ComponentMotionPort } from './motion'\r\nimport type { InteractionAction, InteractionTrigger } from '../../interactionTypes'\r\n\r\nexport type ComponentMediaChannel = 'music' | 'narration' | 'sfx' | 'ui' | 'video'\r\nexport interface ComponentMediaState { paused: boolean; currentTime: number; loop: boolean }\r\nexport type ComponentMediaCommand =\r\n  | { type: 'play' } | { type: 'pause' } | { type: 'seek'; seconds: number }\r\n  | { type: 'loop'; value: boolean } | { type: 'mix'; volume: number; muted: boolean }\r\nexport interface ComponentMediaRegistrationOptions {\r\n  kind: 'audio' | 'video'\r\n  channel: ComponentMediaChannel\r\n  volume: number\r\n  muted: boolean\r\n  initial: ComponentMediaState\r\n}\r\nexport interface ComponentMediaRegistration {\r\n  update(options: Partial<Pick<ComponentMediaRegistrationOptions, 'channel' | 'volume' | 'muted'>>): void\r\n  report(state: ComponentMediaState, event?: 'play' | 'pause' | 'ended'): void\r\n  dispose(): void\r\n}\r\n/** The callback executes in its caller's realm; transport carries commands and acknowledgements only. */\r\nexport interface ComponentMediaPort {\r\n  register(options: ComponentMediaRegistrationOptions, command: (command: ComponentMediaCommand) => boolean | Promise<boolean>): ComponentMediaRegistration\r\n  interruptBackground(mode: 'none' | 'duck' | 'pause' | 'stop'): { release(): void }\r\n}\r\nexport interface ComponentInteractionPort {\r\n  currentSurfaceId(): string | null\r\n  currentStateId(): string | null\r\n  courseState: { get(key: string): unknown; set(key: string, value: unknown): void }\r\n  subscribeTrigger(trigger: InteractionTrigger, listener: (payload?: unknown) => boolean | void | PromiseLike<boolean | void>): () => void\r\n  executeAction(action: InteractionAction, context: { signal: AbortSignal; ruleId: string; stepId: string; restartFromBeginning: boolean; onNavigationCommit?: () => void }): boolean | void | PromiseLike<boolean | void>\r\n  report(message: string): void\r\n}\r\nexport interface ComponentPresentationPort {\r\n  feedback(text?: string): { setText(text: string): Promise<boolean>; dispose(): void }\r\n  visibility(visible?: boolean): { setVisible(visible: boolean): Promise<boolean>; dispose(): void }\r\n}\r\n\r\n/** Every mounted implementation receives a fresh scope; state never writes author data. */\r\nexport interface ComponentRuntimeScope {\r\n  readonly runScopeId: string\r\n  readonly instanceId: string\r\n  readonly generation: number\r\n  readonly signal: AbortSignal\r\n  /** Whether this mount survives; temporary offscreen pause does not revoke it. */\r\n  isActive(): boolean\r\n  cleanup(dispose: () => void): void\r\n  target(reference: ComponentTarget): ComponentRuntimeTarget | null\r\n  events: {\r\n    emit(name: string, value: JsonValue): void\r\n    /** __runtime.activity replays the current {active, visible, playing} for this instance. */\r\n    subscribe(name: string, listener: (value: JsonValue) => void): () => void\r\n  }\r\n  state: {\r\n    get(name: string): JsonValue | undefined\r\n    set(name: string, value: JsonValue): void\r\n    subscribe(name: string, listener: (value: JsonValue | undefined) => void): () => void\r\n  }\r\n}\r\n\r\nexport interface ComponentRuntimeTarget {\r\n  readonly instanceId: string\r\n  /** Headless targets and behavior instances need no DOM root. */\r\n  readonly element?: HTMLElement\r\n  /** A semantic range can span several formatted runs. */\r\n  readonly elements?: readonly HTMLElement[]\r\n  readonly motion?: ComponentMotionPort\r\n  readonly presentation?: ComponentPresentationPort\r\n  read(): JsonValue\r\n  emit(name: string, value: JsonValue): void\r\n}\r\n\r\n/** Identity is local to one component/HTML document; scopes contain real state or data-item keys. */\r\nexport type ComponentAuthorScope = Record<string, string>\r\nexport interface ComponentAuthorBindingStep { tag: string; index: number; attributes?: Record<string, string> }\r\nexport interface ComponentAuthorBinding {\r\n  kind: 'dom'\r\n  path: ComponentAuthorBindingStep[]\r\n  textIndex?: number\r\n  baseline: string\r\n  context?: { path: ComponentAuthorBindingStep[]; value: string }[]\r\n}\r\n/** Author increments compose with the program's own transform; width/height resize its content box. */\r\nexport interface ComponentAuthorGeometry {\r\n  translateX?: number; translateY?: number; scaleX?: number; scaleY?: number\r\n  width?: number; height?: number; rotation?: number\r\n}\r\nexport interface ComponentAuthorRecord {\r\n  kind: 'text' | 'image'\r\n  scope?: ComponentAuthorScope\r\n  binding: ComponentAuthorBinding\r\n  overrides: { text?: string; src?: string; style?: Record<string, string>; geometry?: ComponentAuthorGeometry }\r\n}\r\n/** Observed border box in its actual DOM parent; the parent map excludes the object itself. */\r\nexport interface ComponentAuthorGeometryObservation {\r\n  frame: ComponentFrame\r\n  parentToInstance: AffineTransform\r\n  author: ComponentAuthorGeometry\r\n  /** Insets to subtract when a border-box gesture writes CSS content-box width/height. */\r\n  boxInsets: { width: number; height: number }\r\n  /** Original CSS transform-origin offset and its response to one CSS px of box resizing. */\r\n  sourceOffset?: { current: { x: number; y: number }; widthDelta: { x: number; y: number }; heightDelta: { x: number; y: number } }\r\n}\r\n\r\n/** Ephemeral observations carry the persistent record needed to commit a first local edit. */\r\nexport interface ComponentAuthorSpotInput {\r\n  kind: 'text' | 'image'\r\n  /** Current computed CSS for the local text tools; never persisted as author data. */\r\n  textStyle?: Partial<Record<'font-family' | 'font-size' | 'color' | 'fill' | 'font-weight' | 'font-style'\r\n    | 'text-decoration-line' | 'background-color' | 'text-align' | 'line-height', string>>\r\n  authorKey?: string\r\n  scope?: ComponentAuthorScope\r\n  binding?: ComponentAuthorBinding\r\n  bindingStatus?: 'bound' | 'unmounted' | 'unresolved' | 'source-required'\r\n  geometry?: ComponentAuthorGeometryObservation\r\n  fieldScope?: 'data' | 'authoring'\r\n  dataPath?: string[]\r\n  sourceRegion?: { kind: 'implementation' | 'data'; path?: string[]; start: number; end: number;\r\n    encoding?: 'html-text' | 'html-attribute' }\r\n  initialValue: JsonValue\r\n  localBounds: ComponentFrame\r\n}\r\nexport interface ComponentAuthorSpot extends ComponentAuthorSpotInput {\r\n  id: string\r\n  instanceId: string\r\n  mountGeneration: number\r\n}\r\n/** A frozen semantic author address, without display geometry or a live mount identity. */\r\nexport type ComponentAuthorField = Pick<ComponentAuthorSpotInput, 'kind' | 'authorKey' | 'scope' | 'binding' | 'bindingStatus'\r\n  | 'fieldScope' | 'dataPath' | 'sourceRegion' | 'initialValue'>\r\n/** A live registration may preview one gesture; callbacks never enter author data or cloned observations. */\r\nexport interface ComponentAuthorPreviewCallbacks {\r\n  previewGeometry(geometry: ComponentAuthorGeometry | null): void\r\n}\r\n\r\n/** Host-derived layout, not author metadata. Only Flow owns the natural height of a reading block. */\r\nexport type ComponentLayoutInput =\r\n  | { mode: 'free-frame' | 'flow-viewport'; inlineSize: number; blockSize: number }\r\n  | { mode: 'flow-content'; inlineSize: number }\r\n\r\nexport interface ComponentLayoutSizeReport {\r\n  /** The host input width used for this measurement, never the content's scrollWidth. */\r\n  inlineSize: number\r\n  blockSize: number\r\n}\r\n\r\n/** Bound to one instance/mount generation; retired ports cannot report into a replacement generation. */\r\nexport interface ComponentLayoutPort {\r\n  read(): ComponentLayoutInput\r\n  subscribe(listener: (layout: ComponentLayoutInput) => void): () => void\r\n  /** A display observation only. The Surface accepts it for the current width and never writes History. */\r\n  reportSize(report: ComponentLayoutSizeReport): void\r\n}\r\n\r\nexport interface ComponentRuntimeContext<Data = JsonValue> {\r\n  /** Host mounts a referenced owned child in its authored inline position. */\r\n  inline?: { mount(instanceId: string, root: HTMLElement): () => void }\r\n  readonly instance: ComponentInstance<Data>\r\n  readonly scope: ComponentRuntimeScope\r\n  readonly root?: HTMLElement\r\n  readonly teacherController?: TeacherControllerPort\r\n  /** Read-only URLs for assets already owned by this document; no file-system access. */\r\n  readonly resources?: { url(assetId: string): string | undefined }\r\n  readonly media?: ComponentMediaPort\r\n  readonly interactions?: ComponentInteractionPort\r\n  readonly authoring?: { register(spot: ComponentAuthorSpotInput, callbacks?: ComponentAuthorPreviewCallbacks): () => void }\r\n  readonly layout?: ComponentLayoutPort\r\n}\r\n\r\n/** Latest per-instance __runtime.activity event; survival is still scope.isActive(). */\r\nexport interface ComponentRuntimeActivity {\r\n  active: boolean\r\n  visible: boolean\r\n  playing: boolean\r\n}\r\n\r\nexport interface MountedComponent<Data = JsonValue> {\r\n  update(instance: ComponentInstance<Data>): void | Promise<void>\r\n  updatePlacement?(frame: ComponentFrame | undefined): void\r\n  /** Cooperative offscreen pause; retains this mount and its local state. */\r\n  suspend?(): void | Promise<void>\r\n  /** Continue this same mount after it becomes active and visible again. */\r\n  resume?(): void | Promise<void>\r\n  dispose(): void | Promise<void>\r\n}\r\n\r\nexport interface ComponentRuntimeImplementation<Data = JsonValue> {\r\n  /** Explicit Source opt-in: prepare its Web data in this realm before mount, without re-importing the module.\r\n   * DOM and listeners belong to mount; parser preparation replaces the initial document. */\r\n  document?: 'web'\r\n  mount(context: ComponentRuntimeContext<Data>): MountedComponent<Data> | Promise<MountedComponent<Data>>\r\n}\r\n",
    "src/shared/contracts/component-platform/teacherController.ts": "import { z } from 'zod'\r\nimport { componentCameraMotionSchema, componentCameraPoseSchema, componentNavigationTransitionSchema, type ComponentCameraPose, type ComponentNavigationMotion, type ComponentCameraMotion } from './navigationMotion'\r\n\r\ntype TeacherNavigationAction =\r\n  | { type: 'step.previous' }\r\n  | { type: 'step.next' }\r\n  | { type: 'scene.previous' }\r\n  | { type: 'scene.next' }\r\n  | { type: 'scene.replay' }\r\n  | { type: 'course.restart' }\r\n  | { type: 'scene.go'; sceneId: string; targetStateId?: string; targetInstanceId?: string }\r\n\r\nexport type TeacherControllerAction =\r\n  | (TeacherNavigationAction & ComponentNavigationMotion)\r\n  | { type: 'scene.open-picker' | 'audio.toggle-mute' | 'player.fullscreen.toggle' }\r\n  | { type: 'camera.present'; pose: ComponentCameraPose; motion?: ComponentCameraMotion }\r\n\r\nconst navigationMotion = { transition: componentNavigationTransitionSchema.optional(), camera: componentCameraMotionSchema.optional() }\r\nexport const teacherControllerActionSchema: z.ZodType<TeacherControllerAction> = z.union([\r\n  z.object({ type: z.enum(['step.previous', 'step.next', 'scene.previous', 'scene.next', 'scene.replay', 'course.restart']), ...navigationMotion }).strict(),\r\n  z.object({ type: z.enum(['scene.open-picker', 'audio.toggle-mute', 'player.fullscreen.toggle']) }).strict(),\r\n  z.object({ type: z.literal('scene.go'), sceneId: z.string().min(1), targetStateId: z.string().optional(), targetInstanceId: z.string().min(1).optional(), ...navigationMotion }).strict(),\r\n  z.object({ type: z.literal('camera.present'), pose: componentCameraPoseSchema, motion: componentCameraMotionSchema.optional() }).strict(),\r\n])\r\nexport interface TeacherControllerSnapshot {\r\n  locationId: string | null\r\n  /** Live host interaction mode; the author's component data and frame are unchanged. */\r\n  interactive?: boolean\r\n  scenes: readonly { id: string; name: string; targets?: readonly {\r\n    id: string; name: string; kind: 'state' | 'camera' | 'heading'; depth?: number\r\n    action: Extract<TeacherControllerAction, { type: 'scene.go' }>\r\n  }[] }[]\r\n  progress: { sceneIndex: number; sceneCount: number; stepIndex: number; stepCount: number; sceneName: string; stepName: string } | null\r\n  /** Unset until the session overrides the authored initial state. */\r\n  collapsed?: boolean\r\n  zoom: number\r\n  /** Current session pose, never an authored frame or path mutation. */\r\n  camera?: ComponentCameraPose\r\n  muted: boolean\r\n  fullscreen: boolean\r\n}\r\n/** One navigation/view owner is shared by the builtin and source proxy. */\r\nexport interface TeacherControllerPort {\r\n  /** Host binds view state to the mounted instance; course navigation stays shared. */\r\n  forInstance?(instanceId: string): TeacherControllerPort\r\n  placement?(): { x: number; y: number }\r\n  subscribePlacement?(listener: () => void): () => void\r\n  read(): TeacherControllerSnapshot\r\n  /** Current owner fact without building the course directory. */\r\n  readLocation(): string | null\r\n  subscribe(listener: () => void): () => void\r\n  /** Actual playback region in the owning document's viewport CSS pixels. */\r\n  viewportBounds?(): { left: number; top: number; right: number; bottom: number } | undefined\r\n  canExecute(action: TeacherControllerAction): boolean\r\n  /**\r\n   * Navigation snapshots are captured/cleaned by the host; only the destination stays live.\r\n   * transition supports code-generated old/new keyframes, duration, delay and CSS easing.\r\n   * camera.present and navigation.camera share the mounted camera owner; pan/Stop/new navigation cancels them.\r\n   * The third argument is a host lifecycle hook at the actual fact commit, never serialized to a source realm.\r\n   */\r\n  execute(action: TeacherControllerAction, signal?: AbortSignal, onCommit?: () => void): Promise<boolean>\r\n  /** Host Stop/lifecycle hook; source callers cancel their request with AbortSignal. */\r\n  cancel?(): void\r\n  setCollapsed(value: boolean): void\r\n  moveBy(dx: number, dy: number): void\r\n  setZoom(value: number): void\r\n  resetView(): void\r\n}\r\n",
    "src/shared/contracts/interaction-v1/types.ts": "import type { RuntimePresentationTransition } from '../runtime/types'\nimport type { ComponentNavigationTransition } from '../component-platform/navigationMotion'\nimport type {\n  CourseStateCondition,\n  CourseStateScalar,\n} from '../course-state/types'\n\n/** Runtime-visible discriminators shared by Schema and generated AI contracts. */\nexport const INTERACTION_TRIGGER_TYPES = [\n  'node.click',\n  'scene.enter',\n  'presentation.enter',\n  'component.event',\n  'runtime.event',\n  'audio.ended',\n  'video.started',\n  'video.paused',\n  'video.ended',\n  'video.time',\n  'node.activated',\n  'animation.completed',\n  'presenter.command',\n  'input.submit',\n] as const\n\nexport const INTERACTION_CONDITION_TYPES = [\n  'presentation.in',\n  'scene.in',\n  'course-state.exists',\n  'course-state.compare',\n] as const\n\nexport const INTERACTION_ACTION_TYPES = [\n  'step.next',\n  'step.previous',\n  'presentation.set',\n  'scene.go',\n  'location.go',\n  'scene.next',\n  'scene.previous',\n  'scene.replay',\n  'course.restart',\n  'course-state.set',\n  'audio.play',\n  'audio.pause',\n  'audio.resume',\n  'audio.stop',\n  'audio.toggle-mute',\n  'video.play',\n  'video.pause',\n  'video.restart',\n  'video.stop',\n  'video.toggle',\n  'video.seek',\n  'node.enter',\n  'node.exit',\n] as const\n\nexport type AudioChannel = 'music' | 'narration' | 'sfx' | 'ui'\n\nexport interface InputSubmitTrigger {\n  type: 'input.submit'\n  nodeId: string\n}\n\nexport type InteractionTrigger =\n  | { type: 'node.click'; nodeId: string }\n  | { type: 'scene.enter' }\n  | { type: 'presentation.enter'; stateId: string }\n  | { type: 'component.event'; nodeId: string; eventName: string }\n  | {\n      type: 'runtime.event'\n      scope: 'scene' | 'global'\n      eventName: string\n    }\n  | { type: 'audio.ended'; soundId: string }\n  | { type: 'video.started'; nodeId: string }\n  | { type: 'video.paused'; nodeId: string }\n  | { type: 'video.ended'; nodeId: string }\n  | { type: 'video.time'; nodeId: string; seconds: number }\n  | { type: 'node.activated'; nodeId: string }\n  | { type: 'animation.completed'; actionId: string }\n  | { type: 'presenter.command'; command: 'next' | 'previous' }\n  | InputSubmitTrigger\n\nexport type InteractionCourseStateCondition =\n  | (Omit<Extract<CourseStateCondition, { type: 'exists' }>, 'type'> & {\n      type: 'course-state.exists'\n    })\n  | (Omit<Extract<CourseStateCondition, { type: 'compare' }>, 'type'> & {\n      type: 'course-state.compare'\n    })\n\n/** Different conditions are ANDed. State ids inside one condition are ORed. */\nexport type InteractionCondition =\n  | {\n      type: 'presentation.in'\n      stateIds: string[]\n    }\n  | {\n      type: 'scene.in'\n      sceneIds: string[]\n    }\n  | InteractionCourseStateCondition\n\ntype AssertExactly<Left, Right> =\n  [Exclude<Left, Right>, Exclude<Right, Left>] extends [never, never]\n    ? true\n    : never\n\nconst triggerTypesMatchContract: AssertExactly<\n  InteractionTrigger['type'],\n  (typeof INTERACTION_TRIGGER_TYPES)[number]\n> = true\n\nconst conditionTypesMatchContract: AssertExactly<\n  InteractionCondition['type'],\n  (typeof INTERACTION_CONDITION_TYPES)[number]\n> = true\n\nexport type AudioActionTarget =\n  | { kind: 'sound'; soundId: string }\n  | { kind: 'channel'; channel: AudioChannel }\n  | { kind: 'all' }\n\nexport interface AudioPlayAction {\n  type: 'audio.play'\n  soundId: string\n  volume?: number\n  loop?: boolean\n  fadeInMs?: number\n  lifetime?: 'scene' | 'course'\n  ifPlaying?: 'restart' | 'continue' | 'ignore'\n}\n\nexport interface AudioPauseAction {\n  type: 'audio.pause'\n  target: AudioActionTarget\n  fadeOutMs?: number\n}\n\nexport interface AudioResumeAction {\n  type: 'audio.resume'\n  target: AudioActionTarget\n  fadeInMs?: number\n}\n\nexport interface AudioStopAction {\n  type: 'audio.stop'\n  target: AudioActionTarget\n  fadeOutMs?: number\n}\n\nexport interface AudioToggleMuteAction {\n  type: 'audio.toggle-mute'\n  target: AudioActionTarget\n}\n\nexport type AudioInteractionAction =\n  | AudioPlayAction\n  | AudioPauseAction\n  | AudioResumeAction\n  | AudioStopAction\n  | AudioToggleMuteAction\n\nexport type VideoInteractionAction =\n  | { type: 'video.play'; nodeId: string }\n  | { type: 'video.pause'; nodeId: string }\n  | { type: 'video.restart'; nodeId: string }\n  | { type: 'video.stop'; nodeId: string }\n  | { type: 'video.toggle'; nodeId: string }\n  | { type: 'video.seek'; nodeId: string; seconds: number }\n\nexport interface CourseStateSetAction {\n  type: 'course-state.set'\n  key: string\n  value: CourseStateScalar\n}\n\nexport type MotionEffect = 'none' | 'fade' | 'slide' | 'scale'\nexport type MotionDirection = 'left' | 'right' | 'up' | 'down'\nexport type MotionEasing = 'linear' | 'ease-in' | 'ease-out' | 'ease-in-out'\n\ninterface NodeMotionActionBase {\n  nodeId: string\n  durationMs: number\n  easing: MotionEasing\n}\n\ntype NodeMotionDescriptor =\n  | { effect: 'slide'; direction: MotionDirection }\n  | { effect: Exclude<MotionEffect, 'slide'>; direction?: never }\n\n/** A host-level entrance/exit action. Timing lives on its enclosing step. */\nexport type NodeMotionAction = (\n  | { type: 'node.enter' }\n  | { type: 'node.exit' }\n) & NodeMotionActionBase & NodeMotionDescriptor\n\n/** Payload family used by both sequential and parallel Project V8 action steps. */\nexport type InteractionActionPayload =\n  | { type: 'step.next'; transition?: ComponentNavigationTransition }\n  | { type: 'step.previous'; transition?: ComponentNavigationTransition }\n  | {\n      type: 'presentation.set'\n      stateId: string\n      transition?: RuntimePresentationTransition\n    }\n  | {\n      type: 'scene.go'\n      sceneId: string\n      /** Omit to enter the target scene's authored initial state. */\n      targetStateId?: string\n      transition?: ComponentNavigationTransition\n    }\n  | { type: 'scene.next'; transition?: ComponentNavigationTransition }\n  | { type: 'location.go'; locationId: string; transition?: ComponentNavigationTransition }\n  | { type: 'scene.previous'; transition?: ComponentNavigationTransition }\n  | { type: 'scene.replay'; transition?: ComponentNavigationTransition }\n  | { type: 'course.restart'; transition?: ComponentNavigationTransition }\n  | CourseStateSetAction\n  | AudioInteractionAction\n  | VideoInteractionAction\n  | NodeMotionAction\n\n/** Action payload carried by a Project V8 interaction step. */\nexport type InteractionAction = InteractionActionPayload\n\nconst actionTypesMatchContract: AssertExactly<\n  InteractionActionPayload['type'],\n  (typeof INTERACTION_ACTION_TYPES)[number]\n> = true\n\nvoid triggerTypesMatchContract\nvoid conditionTypesMatchContract\nvoid actionTypesMatchContract\n\nexport interface InteractionActionStep {\n  /** Stable within one scene/global interaction scope; completion triggers reference it. */\n  id: string\n  start: 'after-previous' | 'with-previous'\n  /** Relative to the triggering event or previous completed action group. */\n  delayMs: number\n  action: InteractionActionPayload\n}\n\nexport interface InteractionRule {\n  id: string\n  name?: string\n  enabled: boolean\n  trigger: InteractionTrigger\n  conditions: InteractionCondition[]\n  /** Steps execute as sequential/parallel groups. Terminal navigation owns the last group. */\n  actions: InteractionActionStep[]\n}\n\nexport type TerminalNavigationAction = Extract<\n  InteractionActionPayload,\n  {\n    type:\n      | 'step.next'\n      | 'step.previous'\n      | 'scene.go'\n      | 'location.go'\n      | 'scene.next'\n      | 'scene.previous'\n      | 'scene.replay'\n      | 'course.restart'\n  }\n>\n\nconst terminalNavigationTypes = new Set<InteractionActionPayload['type']>([\n  'step.next',\n  'step.previous',\n  'scene.go',\n  'location.go',\n  'scene.next',\n  'scene.previous',\n  'scene.replay',\n  'course.restart',\n])\n\nexport function isTerminalNavigationAction(\n  action: InteractionActionPayload,\n): action is TerminalNavigationAction {\n  return terminalNavigationTypes.has(action.type)\n}\n\nexport function isAudioInteractionAction(\n  action: InteractionActionPayload,\n): action is AudioInteractionAction {\n  return action.type.startsWith('audio.')\n}\n\nexport function isVideoInteractionAction(\n  action: InteractionActionPayload,\n): action is VideoInteractionAction {\n  return action.type.startsWith('video.')\n}\n\nexport function isNodeMotionAction(\n  action: InteractionActionPayload,\n): action is NodeMotionAction {\n  return action.type === 'node.enter' || action.type === 'node.exit'\n}\n"
