  "version": 1
}

files.tools/document.export.json:
{
  "description": "将已授权课件的当前内容导出；省略 format 默认离线单 HTML，保留互动并可直接运行。也可明确选择 html-online、web-package、pptx、pdf 或 Flow 讲义 docx；PPTX/PDF/DOCX 是静态格式，不承载自编程序互动。相对 destination 使用任务工作空间根目录。消费与人工导出相同的 V10 格式生产器。返回 generated 或 written 的真实状态。同任务同文档的既有导出未被修改时可原位更新，其他同名文件不覆盖。",
  "inputSchema": {
    "$defs": {
      "__schema0": {
        "items": {
          "$ref": "#/$defs/__schema1"
        },
        "minItems": 1,
        "type": "array"
      },
      "__schema1": {
        "minLength": 1,
        "type": "string"
      }
    },
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "properties": {
      "destination": {
        "maxLength": 1024,
        "minLength": 1,
        "type": "string"
      },
      "format": {
        "enum": [
          "html-offline",
          "html-online",
          "web-package",
          "pptx",
          "pdf",
          "docx"
        ],
        "type": "string"
      },
      "options": {
        "additionalProperties": false,
        "properties": {
          "orientation": {
            "enum": [
              "auto",
              "portrait",
              "landscape"
            ],
            "type": "string"
          },
          "pageIds": {
            "$ref": "#/$defs/__schema0",
            "description": "静态格式页面选择与顺序：surfaceId 或 Spatial 的 surfaceId:frameId；省略时按作品顺序输出。"
          },
          "pageSize": {
            "enum": [
              "A4",
              "letter",
              "surface-native"
            ],
            "type": "string"
          }
        },
        "type": "object"
      },
      "target": {
        "maxLength": 200,
        "minLength": 1,
        "type": "string"
      }
    },
    "required": [
      "target"
    ],
    "type": "object"
  },
  "invocation": "静态目录只说明已登记接口；当前运行是否可调用、文档范围、写权限、短句柄和服务配置，以宿主本轮发现与实际回执为准。",
  "manual": {
    "group": "edit",
    "label": "导出文档",
    "targetKinds": [
      "document"
    ]
  },
  "name": "document.export",
  "version": 1
}

