    "$defs": {
      "__schema0": {
        "type": "string"
      }
    },
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "properties": {
      "style": {
        "additionalProperties": false,
        "properties": {
          "baseline": {
            "maximum": 1,
            "minimum": -1,
            "type": "number"
          },
          "bold": {
            "type": "boolean"
          },
          "color": {
            "$ref": "#/$defs/__schema0"
          },
          "emphasis": {
            "type": "boolean"
          },
          "fontFamily": {
            "maxLength": 300,
            "minLength": 1,
            "type": "string"
          },
          "fontSize": {
            "maximum": 400,
            "minimum": 8,
            "type": "number"
          },
          "highlightColor": {
            "anyOf": [
              {
                "$ref": "#/$defs/__schema0"
              },
              {
                "type": "null"
              }
            ]
          },
          "italic": {
            "type": "boolean"
          },
          "strike": {
            "type": "boolean"
          },
          "underline": {
            "type": "boolean"
          }
        },
        "type": "object"
      },
      "target": {
        "minLength": 1,
        "type": "string"
      }
    },
    "required": [
      "target",
      "style"
    ],
    "type": "object"
  },
  "invocation": "静态目录只说明已登记接口；当前运行是否可调用、文档范围、写权限、短句柄和服务配置，以宿主本轮发现与实际回执为准。",
  "manual": {
    "group": "edit",
    "label": "设置文字格式",
    "targetKinds": [
